package io.fireflysoftware.domain.lending.loan.origination.core.evidence.impl;
import io.fireflysoftware.domain.lending.loan.origination.core.evidence.*;
import io.fireflysoftware.commons.ecm.sdk.model.EvidenceUploadReceipt;
import io.fireflysoftware.core.lending.origination.sdk.model.EvidenceAssociationReceipt;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.core.io.*;
import org.springframework.http.*;
import org.springframework.web.reactive.function.client.WebClientResponseException;
import reactor.test.StepVerifier;
import static org.assertj.core.api.Assertions.*;

/** Genuine generated models/error contract and real Resource bytes only; not an owning HTTP/Main or business integration claim. */
class ManagedDocumentSdkContractTest {
    final UUID action=UUID.randomUUID(),app=UUID.randomUUID(),party=UUID.randomUUID(),loan=UUID.randomUUID(),tenant=UUID.randomUUID(),document=UUID.randomUUID();
    final Instant now=Instant.parse("2026-11-01T00:00:00.123456Z");
    final ManagedEvidenceAuthority.Scope scope=new ManagedEvidenceAuthority.Scope(action,app,party,loan,tenant,"https://issuer.invalid","opaque:human","platform",now,0,now.plusSeconds(5));
    @Test void actualGeneratedOwnerReceiptRetainsFullTypedOriginalIdentity(){var value=TokenExchangedManagedDocumentEvidencePortImpl.stored(scope,wire(new byte[]{1,2,3}));assertThat(value.actionId()).isEqualTo(action);assertThat(value.applicationId()).isEqualTo(app);assertThat(value.partyId()).isEqualTo(party);assertThat(value.resourceTenantId()).isEqualTo(tenant);assertThat(value.documentId()).isEqualTo(document);assertThat(value.ownerIntentDigest()).isEqualTo("a".repeat(64));assertThat(value.storedAt()).isEqualTo(now);var attached=TokenExchangedManagedLoanEvidencePortImpl.attached(scope,loanWire(new byte[]{1,2,3}));assertThat(attached.documentStoredAt()).isEqualTo(now);assertThat(attached.attachedAt()).isEqualTo(now);assertThat(attached.documentResourceTenantId()).isEqualTo(tenant);assertThat(attached.resourceTenantId()).isEqualTo(loan);assertThat(attached.ownerIntentDigest()).isEqualTo("b".repeat(64));}
    @Test void equalLengthWrongActualBytesCannotEchoTheReceiptDigest(){byte[] original={1,2,3};var stored=TokenExchangedManagedDocumentEvidencePortImpl.stored(scope,wire(original));StepVerifier.create(TokenExchangedManagedDocumentEvidencePortImpl.content(scope,stored,response(stored,new byte[]{3,2,1}))).expectError().verify();}
    @Test void actualTwoMiBBoundaryContentIsHashedAndAccepted(){byte[] bytes=new byte[2097152];Arrays.fill(bytes,(byte)37);var stored=TokenExchangedManagedDocumentEvidencePortImpl.stored(scope,wire(bytes));StepVerifier.create(TokenExchangedManagedDocumentEvidencePortImpl.content(scope,stored,response(stored,bytes))).assertNext(value->{assertThat(value.contentLength()).isEqualTo(bytes.length);assertThat(value.contentDigest()).isEqualTo(hash(bytes));assertThat(value.documentId()).isEqualTo(document);}).verifyComplete();}
    @Test void excessBodyOrForeignReceiptCannotBecomeVerifiedReadback(){byte[] bytes={1,2,3};var stored=TokenExchangedManagedDocumentEvidencePortImpl.stored(scope,wire(bytes));StepVerifier.create(TokenExchangedManagedDocumentEvidencePortImpl.content(scope,stored,response(stored,new byte[2097153]))).expectError().verify();assertThatThrownBy(()->TokenExchangedManagedDocumentEvidencePortImpl.stored(scope,wire(bytes).partyId(UUID.randomUUID()))).isInstanceOf(RuntimeException.class);}
    @Test void untyped503AfterDispatchRemainsUnknown(){var error=TokenExchangedManagedDocumentEvidencePortImpl.writeFailure(scope,error("{\"message\":\"unavailable\"}"));assertThat(error).isInstanceOf(ManagedDocumentEvidencePort.OutcomeFailure.class);assertThat(((ManagedDocumentEvidencePort.OutcomeFailure)error).outcome()).isEqualTo(ManagedDocumentEvidencePort.CustodyOutcome.OUTCOME_UNKNOWN);}
    @Test void typedOriginalActionOwnerFailureDistinguishesRefusalFromKnownCommit(){
        for(String outcome:List.of("REFUSED","COMMITTED_RESPONSE_UNAVAILABLE")){String body="{\"actionId\":\""+action+"\",\"code\":\"DOCUMENT_EVIDENCE_"+outcome+"\",\"outcome\":\""+outcome+"\",\"recovery\":\"SAME_ACTION_OBSERVE_OR_EXACT_REPLAY\"}";var error=(ManagedDocumentEvidencePort.OutcomeFailure)TokenExchangedManagedDocumentEvidencePortImpl.writeFailure(scope,error(body));assertThat(error.matches(scope)).isTrue();assertThat(error.outcome()).isEqualTo("REFUSED".equals(outcome)?ManagedDocumentEvidencePort.CustodyOutcome.PROVEN_REFUSED:ManagedDocumentEvidencePort.CustodyOutcome.COMMITTED);assertThat(error.known()).isEmpty();String loanBody=body.replace("DOCUMENT_EVIDENCE_","LENDING_EVIDENCE_ASSOCIATION_");var loanError=(ManagedLoanEvidencePort.OutcomeFailure)TokenExchangedManagedLoanEvidencePortImpl.writeFailure(scope,error(loanBody));assertThat(loanError.matches(scope)).isTrue();assertThat(loanError.outcome()).isEqualTo("REFUSED".equals(outcome)?ManagedLoanEvidencePort.AssociationOutcome.PROVEN_REFUSED:ManagedLoanEvidencePort.AssociationOutcome.COMMITTED);assertThat(loanError.known()).isEmpty();}
    }
    @Test void foreignActionTypedFailureCannotResolveThisDispatchedWrite(){String body="{\"actionId\":\""+UUID.randomUUID()+"\",\"code\":\"DOCUMENT_EVIDENCE_REFUSED\",\"outcome\":\"REFUSED\",\"recovery\":\"SAME_ACTION_OBSERVE_OR_EXACT_REPLAY\"}";var failure=(ManagedDocumentEvidencePort.OutcomeFailure)TokenExchangedManagedDocumentEvidencePortImpl.writeFailure(scope,error(body));assertThat(failure.outcome()).isEqualTo(ManagedDocumentEvidencePort.CustodyOutcome.OUTCOME_UNKNOWN);}
    EvidenceUploadReceipt wire(byte[] bytes){var receipt=new EvidenceUploadReceipt().actionId(action).applicationId(app).partyId(party).resourceTenantId(tenant).documentId(document).fileName("proof.pdf").documentTypeCode("ID_DOCUMENT").mediaType("application/pdf").contentLength((long)bytes.length).contentDigest(hash(bytes)).intentDigest("a".repeat(64)).replayed(true);try{var setter=EvidenceUploadReceipt.class.getMethod("setStoredAt",Instant.class);setter.invoke(receipt,now);}catch(ReflectiveOperationException missing){throw new AssertionError("Fresh owner-generated offset-preserving Instant contract required",missing);}return receipt;}
    EvidenceAssociationReceipt loanWire(byte[] bytes){return new EvidenceAssociationReceipt().actionId(action).applicationId(app).partyId(party).resourceTenantId(loan).associationId(UUID.randomUUID()).documentResourceTenantId(tenant).documentId(document).documentTypeId(UUID.randomUUID()).documentTypeCode("ID_DOCUMENT").fileName("proof.pdf").mediaType("application/pdf").contentLength((long)bytes.length).contentDigest(hash(bytes)).documentIntentDigest("a".repeat(64)).documentStoredAt(now).state("ATTACHED").verificationStatus("PENDING").attachedAt(now).replayed(true).intentDigest("b".repeat(64));}
    ResponseEntity<Resource> response(ManagedDocumentEvidencePort.Stored stored,byte[] bytes){return ResponseEntity.ok().contentType(MediaType.APPLICATION_OCTET_STREAM).contentLength(stored.contentLength()).header("X-Evidence-Content-SHA256",stored.contentDigest()).body(new ByteArrayResource(bytes));}
    WebClientResponseException error(String body){return new WebClientResponseException(503,"Unavailable",HttpHeaders.EMPTY,body.getBytes(StandardCharsets.UTF_8),StandardCharsets.UTF_8);}
    static String hash(byte[] bytes){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes));}catch(NoSuchAlgorithmException impossible){throw new AssertionError(impossible);}}
}
